export class AncienComposant implements OnInit, OnDestroy {
  private readonly http = inject(HttpClient);
  private sub?: Subscription;

  // \u26A0\uFE0F 3 variables d'\xE9tat manuelles \xE0 synchroniser !
  articles: ArticleDTO[] = [];
  isLoading = false;
  error: any = null;

  ngOnInit() {
    this.chargerArticles();
  }

  chargerArticles() {
    this.isLoading = true;
    this.error = null;

    // \u26A0\uFE0F Risque de fuite de m\xE9moire si pas d'unsubscribe !
    this.sub = this.http.get<ArticleDTO[]>('/api/articles')
      .subscribe({
        next: (data) => {
          this.articles = data;
          this.isLoading = false;
        },
        error: (err) => {
          this.error = err;
          this.isLoading = false;
        }
      });
  }

  ngOnDestroy() {
    this.sub?.unsubscribe(); // \u26A0\uFE0F Lourd et oubli fr\xE9quent
  }
}`),d()(),u(17,"div",18)(18,"div",19),l(19,"\u26A0\uFE0F Points de friction majeurs :"),d(),u(20,"ul",20)(21,"li"),l(22,"Fuites de m\xE9moire silencieuses si l'abonnement n'est pas nettoy\xE9 dans "),u(23,"code"),l(24,"ngOnDestroy"),d(),l(25,"."),d(),u(26,"li"),l(27,"Mise \xE0 jour manuelle des bool\xE9ens "),u(28,"code"),l(29,"isLoading"),d(),l(30," et "),u(31,"code"),l(32,"error"),d(),l(33," dans les callbacks."),d(),u(34,"li"),l(35,"Absence d'annulation automatique si l'utilisateur change de filtre en cours de route."),d()()()(),u(36,"div",21)(37,"div",14)(38,"span",22),l(39,"Monde Moderne \xB7 Angular 22 Signals"),d(),u(40,"span",23),l(41,"1 ligne d\xE9clarative"),d()(),u(42,"pre",17)(43,"code"),l(44,`// \u2705 Monde Moderne : D\xE9claratif Signal-First
